mapper.select:
WITH input(user_id,session_key,upload,download,initial_upload,initial_download,at,ip,torrent_id,seeding,observation_key) AS MATERIALIZED ( VALUES
(#{uid}::bigint,#{r.key}::uuid,#{r.upload}::bigint,#{r.download}::bigint, #{r.initialUpload}::bigint,#{r.initialDownload}::bigint,#{r.at}::timestamptz, #{r.ip}::inet,#{r.torrentId}::bigint,#{r.seeding}::boolean,#{r.observationKey}::uuid)
), checkpoint AS ( INSERT INTO user_lifetime_traffic_checkpoint AS c (user_id,session_key,uploaded,downloaded,upload_delta,download_delta) SELECT user_id,session_key,upload,download,initial_upload,initial_download FROM input ORDER BY torrent_id,session_key ON CONFLICT(user_id,session_key) DO UPDATE SET upload_delta=GREATEST(EXCLUDED.uploaded-c.uploaded,0), download_delta=GREATEST(EXCLUDED.downloaded-c.downloaded,0), uploaded=GREATEST(c.uploaded,EXCLUDED.uploaded), downloaded=GREATEST(c.downloaded,EXCLUDED.downloaded) RETURNING user_id,session_key,upload_delta,download_delta ), peers AS MATERIALIZED ( SELECT DISTINCT ua.owner,i.session_key,i.at,i.observation_key FROM input i JOIN userapps_heartbeat hb ON hb.ip=i.ip AND hb.first_seen_at <= i.at AND hb.last_seen_at >= i.at-(#{heartbeatWindowMillis}::bigint * interval '1 millisecond') JOIN userapp ua ON ua.id=hb.userapp_id WHERE NOT EXISTS(SELECT 1 FROM user_account_deletion_request d WHERE d.user_id=ua.owner AND d.status='COMPLETED') ), events AS ( INSERT INTO user_career_events(user_id,kind,fingerprint,observed_at) SELECT user_id,'swarm' AS kind,session_key,at FROM input WHERE (SELECT count(*) FROM checkpoint) >= 0 UNION ALL SELECT owner,'observation',observation_key,at FROM peers WHERE owner <> #{uid} AND (SELECT count(*) FROM checkpoint) >= 0 ORDER BY 1,2,3 ON CONFLICT DO NOTHING RETURNING user_id,kind,observed_at ), latest AS ( SELECT DISTINCT ON (user_id,torrent_id) user_id,torrent_id,at,seeding FROM input ORDER BY user_id,torrent_id,at DESC,session_key ), time_update AS ( INSERT INTO user_career_torrent_time AS a(user_id,torrent_id,last_seen,was_seeding) SELECT user_id,torrent_id,at,seeding FROM latest WHERE (SELECT count(*) FROM events) >= 0 ORDER BY user_id,torrent_id ON CONFLICT(user_id,torrent_id) DO UPDATE SET seeding=a.seeding+CASE WHEN a.was_seeding AND EXCLUDED.last_seen>a.last_seen THEN tstzmultirange(tstzrange(a.last_seen,LEAST(EXCLUDED.last_seen,a.last_seen+(#{activityWindowMillis}::bigint * interval '1 millisecond')),'[)')) ELSE '{}'::tstzmultirange END, downloading=a.downloading+CASE WHEN NOT a.was_seeding AND EXCLUDED.last_seen>a.last_seen THEN tstzmultirange(tstzrange(a.last_seen,LEAST(EXCLUDED.last_seen,a.last_seen+(#{activityWindowMillis}::bigint * interval '1 millisecond')),'[)')) ELSE '{}'::tstzmultirange END, was_seeding=CASE WHEN EXCLUDED.last_seen>a.last_seen THEN EXCLUDED.was_seeding ELSE a.was_seeding END, last_seen=GREATEST(a.last_seen,EXCLUDED.last_seen) RETURNING new.user_id, new.seeding-COALESCE(old.seeding,'{}'::tstzmultirange) AS seed_added, (new.downloading-new.seeding)-COALESCE(old.downloading-old.seeding,'{}'::tstzmultirange) AS down_added, COALESCE(old.downloading-old.seeding,'{}'::tstzmultirange)-(new.downloading-new.seeding) AS down_removed ), time_delta AS ( SELECT t.user_id,m.seed,m.sign,period FROM time_update t CROSS JOIN LATERAL (VALUES (TRUE,1,t.seed_added),(FALSE,1,t.down_added),(FALSE,-1,t.down_removed)) m(seed,sign,ranges) CROSS JOIN LATERAL unnest(m.ranges) period ), daily_values AS ( SELECT c.user_id,(i.at AT TIME ZONE 'UTC')::date AS day,c.upload_delta::numeric AS upload, c.download_delta::numeric AS download,0::numeric AS upload_ack,0::numeric AS download_ack, 0::numeric AS loss,0::numeric AS seeding,0::numeric AS downloading, 0::bigint AS swarm_events,0::bigint AS ban_events,0::bigint AS observation_events FROM checkpoint c JOIN input i USING(user_id,session_key) UNION ALL SELECT p.owner,(p.at AT TIME ZONE 'UTC')::date,0,0,c.download_delta,c.upload_delta,0,0,0,0,0,0 FROM peers p JOIN checkpoint c USING(session_key) UNION ALL SELECT t.user_id,days.day,0,0,0,0,0, CASE WHEN t.seed THEN t.sign*extract(epoch FROM upper(clipped.period)-lower(clipped.period)) ELSE 0 END, CASE WHEN NOT t.seed THEN t.sign*extract(epoch FROM upper(clipped.period)-lower(clipped.period)) ELSE 0 END,0,0,0 FROM time_delta t CROSS JOIN LATERAL ( SELECT (lower(t.period) AT TIME ZONE 'UTC')::date+n AS day FROM generate_series(0,(upper(t.period) AT TIME ZONE 'UTC')::date-(lower(t.period) AT TIME ZONE 'UTC')::date) n ) days CROSS JOIN LATERAL (SELECT t.period * tstzrange(days.day::timestamp AT TIME ZONE 'UTC', (days.day+1)::timestamp AT TIME ZONE 'UTC','[)') AS period) clipped WHERE NOT isempty(clipped.period) UNION ALL SELECT user_id,(observed_at AT TIME ZONE 'UTC')::date,0,0,0,0,0,0,0, CASE WHEN kind='swarm' THEN 1 ELSE 0 END,0, CASE WHEN kind='observation' THEN 1 ELSE 0 END FROM events ) SELECT user_id,day,SUM(upload) AS upload,SUM(download) AS download, SUM(upload_ack) AS upload_ack,SUM(download_ack) AS download_ack,SUM(loss) AS loss, SUM(seeding) AS seeding,SUM(downloading) AS downloading, SUM(swarm_events)::bigint AS swarm_events,SUM(ban_events)::bigint AS ban_events, SUM(observation_events)::bigint AS observation_events FROM daily_values GROUP BY user_id,day

mapper.insert:
INSERT INTO user_traffic_daily AS d(user_id,day,upload,download,upload_ack,download_ack,loss,seeding,downloading) SELECT user_id,day,SUM(upload),SUM(download),SUM(upload_ack),SUM(download_ack),SUM(loss),SUM(seeding),SUM(downloading) FROM (VALUES
(#{r.userId}::bigint,#{r.day}::date,#{r.upload}::numeric,#{r.download}::numeric, #{r.uploadAck}::numeric,#{r.downloadAck}::numeric,#{r.loss}::numeric, #{r.seeding}::numeric,#{r.downloading}::numeric)
) AS deltas(user_id,day,upload,download,upload_ack,download_ack,loss,seeding,downloading) GROUP BY user_id,day ORDER BY user_id,day ON CONFLICT(user_id,day) DO UPDATE SET upload=d.upload+EXCLUDED.upload,download=d.download+EXCLUDED.download, upload_ack=d.upload_ack+EXCLUDED.upload_ack,download_ack=d.download_ack+EXCLUDED.download_ack, loss=d.loss+EXCLUDED.loss,seeding=d.seeding+EXCLUDED.seeding,downloading=d.downloading+EXCLUDED.downloading
